import java.util.Scanner;

public class Main {
    static final int MAX_LIMIT = 1000000 + 100000;
    static final long MOD_CONST = 1000000007L;

    static long p_value, k_value;
    static int count_total;
    static long answer_value;
    static int[] visited_flags = new int[MAX_LIMIT];
    static int[] val_storage = new int[MAX_LIMIT];

    static void mod_apply(long[] x) {
        x[0] = ((x[0] % MOD_CONST) + MOD_CONST) % MOD_CONST;
    }

    static void bfs_search(int x) {
        count_total++;
        int start_point = x;
        long weight = 1;
        do {
            visited_flags[x] = 1;
            x = (int)((x * k_value) % p_value);
            weight = (weight * k_value) % p_value;
        } while (x != start_point);
        long[] answerHolder = {answer_value};
        if (weight == 1) {
            answerHolder[0] = (answerHolder[0] * p_value) % MOD_CONST;
        }
        answer_value = answerHolder[0];
    }

    static void process_solution() {
        if (k_value == 0) {
            long product = 1;
            for (int i = 1; i <= p_value - 1; i++) {
                product = (product * p_value) % MOD_CONST;
            }
            System.out.println(product);
            return;
        }
        answer_value = 1;
        for (int i = 0; i < p_value; i++) {
            if (visited_flags[i] == 0)
                bfs_search(i);
        }
        System.out.println(answer_value);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        p_value = sc.nextLong();
        k_value = sc.nextLong();
        process_solution();
        sc.close();
    }
}
